class Solution {
public:
    vector<int> maxSlidingWindow(vector<int>& nums, int k) {
        int n = nums.size();
        vector<int> ans;
        ans.reserve(n - k + 1);
        deque<int> dq;               // stores indices, values decreasing

        for (int i = 0; i < n; ++i) {
            // Remove indices that are out of the current window
            if (!dq.empty() && dq.front() <= i - k)
                dq.pop_front();

            // Preserve decreasing order: discard smaller (or equal) values
            while (!dq.empty() && nums[i] >= nums[dq.back()])
                dq.pop_back();

            dq.push_back(i);

            // Record the maximum for windows that are fully formed
            if (i >= k - 1)
                ans.push_back(nums[dq.front()]);
        }
        return ans;
    }
};
